  // Load and Migrate/Sync reviews from backend database (SQLite/PostgreSQL compatible)
  useEffect(() => {
    if (!isAuthenticated) return;
    let isMounted = true;
    const initAndSyncReviews = async () => {
      try {
        const data = await apiService.getReviews();
        if (data && data.success && Array.isArray(data.reviews)) {
          if (!isMounted) return;
          if (data.reviews.length === 0) {
            const stored = localStorage.getItem('allReviews');
            let localReviews = null;
            try {
              localReviews = stored ? JSON.parse(stored) : null;
            } catch (e) {}
            if (localReviews && Array.isArray(localReviews) && localReviews.length > 0) {
              const syncData = await apiService.syncReviews(localReviews);
              if (syncData && syncData.success) {
                const reloadData = await apiService.getReviews();
                if (reloadData && reloadData.success && Array.isArray(reloadData.reviews) && isMounted) {
                  setAllReviews(reloadData.reviews);
                }
              }
            }
          } else {
            setAllReviews(data.reviews);
          }
        }
      } catch (err: any) {
        console.warn("Graceful fallback: Reviews sync from database will use local storage cache:", err?.message || err);
      }
    };
    initAndSyncReviews();
    return () => {
      isMounted = false;
    };
  }, [isAuthenticated]);

  // Load and Sync Cloud Database Migration for Halls, Services, Bookings, Support, and Regions
  useEffect(() => {
    if (!isAuthenticated) return;
    const performCloudDataSync = async () => {
      try {
        const isMigrated = localStorage.getItem('CLOUD_MIGRATION_COMPLETED_V2') === 'true';
        
        if (!isMigrated) {
          const rawHalls = localStorage.getItem('PLATFORM_HALLS_V4') || localStorage.getItem('PLATFORM_HALLS');
          const rawServices = localStorage.getItem('PLATFORM_SERVICES_V4') || localStorage.getItem('PLATFORM_SERVICES');
          const rawBookings = localStorage.getItem('PLATFORM_BOOKINGS_V4') || localStorage.getItem('PLATFORM_BOOKINGS');
          const rawSupportReqs = localStorage.getItem('PLATFORM_SUPPORT_REQUESTS');
          const rawTickets = localStorage.getItem('SERVICE_TICKETS');
          const rawRegions = localStorage.getItem('SYSTEM_REGIONS');

          const clientHalls = rawHalls ? JSON.parse(rawHalls) : halls;
          const clientServices = rawServices ? JSON.parse(rawServices) : services;
          const clientBookings = rawBookings ? JSON.parse(rawBookings) : bookings;
          const clientSupportRequests = rawSupportReqs ? JSON.parse(rawSupportReqs) : supportServiceRequests;
          const clientSupportTickets = rawTickets ? JSON.parse(rawTickets) : supportTickets;
          const clientRegions = rawRegions ? JSON.parse(rawRegions) : regions;

          const syncRes = await apiService.syncHallsAndServices(
            clientHalls,
            clientServices,
            clientBookings,
            clientSupportTickets,
            clientSupportRequests,
            clientRegions
          );

          if (syncRes && syncRes.success) {
            localStorage.setItem('CLOUD_MIGRATION_COMPLETED_V2', 'true');
            // Remove bloated legacy mock keys from localStorage
            localStorage.removeItem('PLATFORM_HALLS_V4');
            localStorage.removeItem('PLATFORM_HALLS');
            localStorage.removeItem('PLATFORM_BOOKINGS_V4');
            localStorage.removeItem('PLATFORM_BOOKINGS');
            localStorage.removeItem('PLATFORM_SERVICES_V4');
            localStorage.removeItem('PLATFORM_SERVICES');
            localStorage.removeItem('SERVICE_TICKETS');
            localStorage.removeItem('PLATFORM_SUPPORT_REQUESTS');
          }
        }

        // Fresh fetch from cloud database
        const [hallsRes, servicesRes, bookingsRes, ticketsRes, reqsRes, sysConfigsRes] = await Promise.allSettled([
          apiService.getHalls(),
          apiService.getServices(),
          apiService.getBookings(),
          apiService.getSupportTickets(),
          apiService.getSupportRequests(),
          apiService.getSystemConfigs()
        ]);

        if (hallsRes.status === 'fulfilled' && hallsRes.value?.success && Array.isArray(hallsRes.value.halls) && hallsRes.value.halls.length > 0) {
          setHalls(hallsRes.value.halls);
        }
        if (servicesRes.status === 'fulfilled' && servicesRes.value?.success && Array.isArray(servicesRes.value.services) && servicesRes.value.services.length > 0) {
          setServices(servicesRes.value.services);
        }
        if (bookingsRes.status === 'fulfilled' && bookingsRes.value?.success && Array.isArray(bookingsRes.value.bookings) && bookingsRes.value.bookings.length > 0) {
          setBookings(bookingsRes.value.bookings);
        }
        if (ticketsRes.status === 'fulfilled' && ticketsRes.value?.tickets && Array.isArray(ticketsRes.value.tickets) && ticketsRes.value.tickets.length > 0) {
          setSupportTickets(ticketsRes.value.tickets);
        }
        if (reqsRes.status === 'fulfilled' && reqsRes.value?.requests && Array.isArray(reqsRes.value.requests) && reqsRes.value.requests.length > 0) {
          setSupportServiceRequests(reqsRes.value.requests);
        }
        if (sysConfigsRes.status === 'fulfilled' && sysConfigsRes.value?.success && sysConfigsRes.value.configs) {
          const sysRegs = sysConfigsRes.value.configs.SYSTEM_REGIONS;
          if (sysRegs && Array.isArray(sysRegs) && sysRegs.length > 0) {
            setRegionsState(sysRegs);
            localStorage.setItem('SYSTEM_REGIONS', JSON.stringify(sysRegs));
          }
        }
      } catch (err) {
        console.error("Failed to perform cloud database sync & fetch:", err);
      }
    };
    performCloudDataSync();
  }, [isAuthenticated]);

