  const submitCustomerReview = async (reviewData: {
    targetType: 'hall' | 'service' | 'provider';
    targetId: number | string;
    targetName: string;
    providerName?: string;
    customerName?: string;
    rating: number;
    comment: string;
  }): Promise<boolean> => {
    const commentText = reviewData.comment || '';
    const check = checkProhibitedContent(commentText);
    if (check.prohibited) {
      showNotification('error', `عذراً! يحتوي التقييم على معلومات تواصل أو ألفاظ محظورة (${check.reason}). يرجى تعديل النص.`);
      return false;
    }

    const finalCustomerName = reviewData.customerName || (currentUser ? (currentUser.name || currentUser.email) : 'عميل منصة ليلة');

    const newReview = {
      id: `rev-${Date.now()}`,
      targetType: reviewData.targetType,
      targetId: reviewData.targetId,
      targetName: reviewData.targetName,
      providerName: reviewData.providerName || '',
      customerName: finalCustomerName,
      rating: reviewData.rating,
      comment: commentText,
      date: new Date().toISOString().split('T')[0],
      status: 'published'
    };

    try {
      const res = await apiService.saveReview(newReview);
      if (res && res.success && res.review) {
        setAllReviews((prev: any[]) => [res.review, ...prev]);
      } else {
        setAllReviews((prev: any[]) => [newReview, ...prev]);
      }
    } catch {
      setAllReviews((prev: any[]) => [newReview, ...prev]);
    }

    // Auto update rating & reviewsCount for Hall if targetType === 'hall'
    if (reviewData.targetType === 'hall') {
      setHalls((prevHalls: any[]) => prevHalls.map((h: any) => {
        if (String(h.id) === String(reviewData.targetId)) {
          const existingReviews = allReviews.filter((r: any) => r.targetType === 'hall' && String(r.targetId) === String(reviewData.targetId));
          const updatedList = [newReview, ...existingReviews];
          const newCount = updatedList.length;
          const newAvg = Number((updatedList.reduce((acc: number, curr: any) => acc + Number(curr.rating || 0), 0) / newCount).toFixed(1));
          return { ...h, rating: newAvg, reviewsCount: newCount };
        }
        return h;
      }));
    }

    // Auto update rating & reviewsCount for Service if targetType === 'service'
    if (reviewData.targetType === 'service') {
      setServices((prevServices: any[]) => prevServices.map((s: any) => {
        if (String(s.id) === String(reviewData.targetId)) {
          const existingReviews = allReviews.filter((r: any) => r.targetType === 'service' && String(r.targetId) === String(reviewData.targetId));
          const updatedList = [newReview, ...existingReviews];
          const newCount = updatedList.length;
          const newAvg = Number((updatedList.reduce((acc: number, curr: any) => acc + Number(curr.rating || 0), 0) / newCount).toFixed(1));
          return { ...s, rating: newAvg, reviewsCount: newCount };
        }
        return s;
      }));
    }

    // Auto update provider rating
    if (reviewData.providerName) {
      setProviders((prevProviders: any[]) => prevProviders.map((p: any) => {
        if (p.name === reviewData.providerName || String(p.id) === String(reviewData.targetId)) {
          const provReviews = [newReview, ...allReviews.filter((r: any) => r.providerName === reviewData.providerName)];
          const newCount = provReviews.length;
          const newAvg = Number((provReviews.reduce((acc: number, curr: any) => acc + Number(curr.rating || 0), 0) / newCount).toFixed(1));
          return { ...p, rating: newAvg };
        }
        return p;
      }));
    }

    showNotification('success', 'شكراً لك! تم استلام وتقييم التجربة بنجاح.');
    return true;
  };

