  const setSubscriptions = (newOrFn: any) => {
    setSubscriptionsState((prev: any) => {
      let next = typeof newOrFn === 'function' ? newOrFn(prev) : newOrFn;
      if (Array.isArray(next)) {
        const uniqueMap = new Map();
        next.forEach((item: any) => {
          if (item && item.name) {
            const key = item.name.trim();
            const existing = uniqueMap.get(key);
            if (!existing || (!isNaN(Number(item.id)) && isNaN(Number(existing.id)))) {
              uniqueMap.set(key, item);
            }
          }
        });
        next = Array.from(uniqueMap.values());
      }
      saveSubscriptions(next);
      return next;
    });
  };

