  const setRegions = (newOrFn: any) => {
    setRegionsState((prev: any) => {
      const next = typeof newOrFn === 'function' ? newOrFn(prev) : newOrFn;
      
      // Schedule the side-effects in a setTimeout to avoid running them synchronously during the React state update callback
      setTimeout(async () => {
        try {
          localStorage.setItem('SYSTEM_REGIONS', JSON.stringify(next));

          const regionNames = next.map((r: any) => r.name);
          const allCities = next.flatMap((r: any) => r.cities || []);
          const uniqueCities = Array.from(new Set(allCities));
          
          localStorage.setItem('SYSTEM_DATastore_regions', JSON.stringify(regionNames));
          localStorage.setItem('SYSTEM_DATastore_cities', JSON.stringify(uniqueCities));
          
          // Persist directly to Cloud Database PlatformConfig
          await apiService.saveSystemConfigs({
            SYSTEM_REGIONS: next,
            SYSTEM_DATastore_regions: regionNames,
            SYSTEM_DATastore_cities: uniqueCities
          });

          window.dispatchEvent(new Event('datastoreUpdated'));
        } catch (e) {
          console.error('Error in setRegions datastore sync:', e);
        }
      }, 0);

      return next;
    });
  };

