  // Modern SQL/SQLite Configurations Live Synchronization System
  const isConfigsSyncReadyRef = React.useRef(false);
  const lastSyncedValuesRef = React.useRef<Record<string, string>>({});

  useEffect(() => {
    if (!isAuthenticated) return;
    const initAndSyncConfigs = async () => {
      try {
        setDbHealthStatus('checking');
        const data = await apiService.getSystemConfigs();
        
        if (data.success) {
          if (data.fallback) {
            setDbHealthStatus('fallback');
            console.warn("⚠️ System loaded in storage fallback mode due to database lockdown.");
          } else {
            setDbHealthStatus('connected');
          }
          setDbLastSyncTime(new Date().toLocaleTimeString('ar-SA'));

          const dbConfigs = data.configs || {};
          
          // Pre-populate baseline values with current states to prevent duplicate triggers on startup
          const defaultBaselines: Record<string, any> = {
            INVENTORY_SETTINGS: inventorySettings,
            SYSTEM_GENERAL_SETTINGS: generalSettings,
            SYSTEM_FINANCIAL_SETTINGS: financialSettingsState,
            ENABLE_FORCE_MAJEURE_PROTOCOL: enableForceMajeureProtocol,
            FORCE_MAJEURE_WINDOW_DAYS: forceMajeureWindowDays,
            SYSTEM_SECURITY_SETTINGS: securityCustomSettings,
            SYSTEM_NOTIFICATION_SETTINGS: notificationSettingsState,
            SYSTEM_LOYALTY_SETTINGS: loyaltyCustomSettings,
            ENABLE_PROVIDER_LEVELS: enableProviderLevels,
            ENABLE_LOYALTY_PROGRAM: enableLoyaltyProgram,
            DISABLE_CHAT_SYSTEM: disableChatSystem,
            TICKET_RETENTION_DAYS: ticketRetentionDays,
            MARKETING_COMMISSION_PERCENTAGE: marketingCommissionPercentage,
            ALLOW_ACCOUNT_DELETION: allowAccountDeletion,
            ACTIVE_SETTLEMENT_METHOD: activeSettlementMethod,
            SETTLEMENT_CONFIGURATION: settlementConfig,
            PROMOTIONS: promotions,
            ad_requests: adRequests,
            internal_ads: internalAds,
            lailah_season_requests: seasonRequests,
            PLATFORM_MAIL_MESSAGES: mailMessages,
            SUPPORT_WORKING_HOURS: workingHours,
            SUPPORT_ALERT_MSG: supportAlertMsg,
            ADMIN_ACTIVE_GATEWAY: adminActiveGateway,
            ADMIN_ENABLED_GATEWAYS: enabledGateways,
            sub_grid_columns: subColCount,
            sub_grid_spacing: subSpacing,
            sub_grid_align_center: subAlignCenter,
            PLATFORM_DATA: platformData,
            PARTIAL_PAYMENT_DEPOSIT_PERCENTAGE: partialPaymentDepositPercentage
          };
          Object.keys(defaultBaselines).forEach(k => {
            lastSyncedValuesRef.current[k] = JSON.stringify(defaultBaselines[k]);
          });
          
          // Overwrite with actual database-loaded values
          Object.keys(dbConfigs).forEach(dbKey => {
            lastSyncedValuesRef.current[dbKey] = JSON.stringify(dbConfigs[dbKey]);
          });
          
          if (dbConfigs['INVENTORY_SETTINGS'] !== undefined) setInventorySettings(dbConfigs['INVENTORY_SETTINGS']);
          if (dbConfigs['SYSTEM_GENERAL_SETTINGS'] !== undefined) setGeneralSettings(dbConfigs['SYSTEM_GENERAL_SETTINGS']);
          if (dbConfigs['SYSTEM_FINANCIAL_SETTINGS'] !== undefined) setFinancialSettingsState(dbConfigs['SYSTEM_FINANCIAL_SETTINGS']);
          if (dbConfigs['ENABLE_FORCE_MAJEURE_PROTOCOL'] !== undefined) setEnableForceMajeureProtocol(dbConfigs['ENABLE_FORCE_MAJEURE_PROTOCOL'] !== false);
          if (dbConfigs['FORCE_MAJEURE_WINDOW_DAYS'] !== undefined) setForceMajeureWindowDays(Number(dbConfigs['FORCE_MAJEURE_WINDOW_DAYS']));
          if (dbConfigs['SYSTEM_SECURITY_SETTINGS'] !== undefined) setSecurityCustomSettings(dbConfigs['SYSTEM_SECURITY_SETTINGS']);
          if (dbConfigs['SYSTEM_NOTIFICATION_SETTINGS'] !== undefined) setNotificationSettingsState(dbConfigs['SYSTEM_NOTIFICATION_SETTINGS']);
          if (dbConfigs['SYSTEM_LOYALTY_SETTINGS'] !== undefined) setLoyaltyCustomSettings(dbConfigs['SYSTEM_LOYALTY_SETTINGS']);
          if (dbConfigs['ENABLE_PROVIDER_LEVELS'] !== undefined) setEnableProviderLevels(dbConfigs['ENABLE_PROVIDER_LEVELS'] !== false);
          if (dbConfigs['ENABLE_LOYALTY_PROGRAM'] !== undefined) setEnableLoyaltyProgram(dbConfigs['ENABLE_LOYALTY_PROGRAM'] !== false);
          if (dbConfigs['DISABLE_CHAT_SYSTEM'] !== undefined) setDisableChatSystem(false);
          if (dbConfigs['TICKET_RETENTION_DAYS'] !== undefined) setTicketRetentionDays(dbConfigs['TICKET_RETENTION_DAYS']);
          if (dbConfigs['MARKETING_COMMISSION_PERCENTAGE'] !== undefined) setMarketingCommissionPercentage(dbConfigs['MARKETING_COMMISSION_PERCENTAGE']);
          if (dbConfigs['ALLOW_ACCOUNT_DELETION'] !== undefined) setAllowAccountDeletion(dbConfigs['ALLOW_ACCOUNT_DELETION'] === true);
          if (dbConfigs['ACTIVE_SETTLEMENT_METHOD'] !== undefined) setActiveSettlementMethod(dbConfigs['ACTIVE_SETTLEMENT_METHOD']);
          if (dbConfigs['SETTLEMENT_CONFIGURATION'] !== undefined) setSettlementConfig(dbConfigs['SETTLEMENT_CONFIGURATION']);
          if (dbConfigs['PROMOTIONS'] !== undefined) setPromotions(dbConfigs['PROMOTIONS']);
          if (dbConfigs['ad_requests'] !== undefined) setAdRequests(dbConfigs['ad_requests']);
          if (dbConfigs['internal_ads'] !== undefined) setInternalAds(dbConfigs['internal_ads']);
          if (dbConfigs['lailah_season_requests'] !== undefined) setSeasonRequests(dbConfigs['lailah_season_requests']);
          if (dbConfigs['PLATFORM_MAIL_MESSAGES'] !== undefined) setMailMessages(dbConfigs['PLATFORM_MAIL_MESSAGES']);
          if (dbConfigs['SUPPORT_WORKING_HOURS'] !== undefined) setWorkingHours(dbConfigs['SUPPORT_WORKING_HOURS']);
          if (dbConfigs['SUPPORT_ALERT_MSG'] !== undefined) setSupportAlertMsg(dbConfigs['SUPPORT_ALERT_MSG']);
          if (dbConfigs['ADMIN_ACTIVE_GATEWAY'] !== undefined) setAdminActiveGateway(dbConfigs['ADMIN_ACTIVE_GATEWAY']);
          if (dbConfigs['ADMIN_ENABLED_GATEWAYS'] !== undefined) setEnabledGateways(dbConfigs['ADMIN_ENABLED_GATEWAYS']);
          if (dbConfigs['sub_grid_columns'] !== undefined) setSubColCount(Number(dbConfigs['sub_grid_columns']));
          if (dbConfigs['sub_grid_spacing'] !== undefined) setSubSpacing(dbConfigs['sub_grid_spacing']);
          if (dbConfigs['sub_grid_align_center'] !== undefined) setSubAlignCenter(dbConfigs['sub_grid_align_center'] === true || dbConfigs['sub_grid_align_center'] === 'true');
          if (dbConfigs['PLATFORM_DATA'] !== undefined) setPlatformData(dbConfigs['PLATFORM_DATA']);
          if (dbConfigs['PARTIAL_PAYMENT_DEPOSIT_PERCENTAGE'] !== undefined) setPartialPaymentDepositPercentage(Number(dbConfigs['PARTIAL_PAYMENT_DEPOSIT_PERCENTAGE']));

          // Reverse migration: push local configurations up to SQL database if not yet stored on backend
          const keysToMigrate = [
            { key: 'INVENTORY_SETTINGS' },
            { key: 'SYSTEM_GENERAL_SETTINGS' },
            { key: 'SYSTEM_FINANCIAL_SETTINGS' },
            { key: 'ENABLE_FORCE_MAJEURE_PROTOCOL' },
            { key: 'FORCE_MAJEURE_WINDOW_DAYS' },
            { key: 'SYSTEM_SECURITY_SETTINGS' },
            { key: 'SYSTEM_NOTIFICATION_SETTINGS' },
            { key: 'SYSTEM_LOYALTY_SETTINGS' },
            { key: 'ENABLE_PROVIDER_LEVELS' },
            { key: 'ENABLE_LOYALTY_PROGRAM' },
            { key: 'DISABLE_CHAT_SYSTEM' },
            { key: 'TICKET_RETENTION_DAYS' },
            { key: 'MARKETING_COMMISSION_PERCENTAGE' },
            { key: 'ALLOW_ACCOUNT_DELETION' },
            { key: 'ACTIVE_SETTLEMENT_METHOD' },
            { key: 'SETTLEMENT_CONFIGURATION' },
            { key: 'PROMOTIONS' },
            { key: 'ad_requests' },
            { key: 'internal_ads' },
            { key: 'lailah_season_requests' },
            { key: 'PLATFORM_MAIL_MESSAGES' },
            { key: 'SUPPORT_WORKING_HOURS' },
            { key: 'SUPPORT_ALERT_MSG' },
            { key: 'ADMIN_ACTIVE_GATEWAY' },
            { key: 'ADMIN_ENABLED_GATEWAYS' },
            { key: 'sub_grid_columns' },
            { key: 'sub_grid_spacing' },
            { key: 'sub_grid_align_center' },
            { key: 'PLATFORM_DATA' },
            { key: 'PARTIAL_PAYMENT_DEPOSIT_PERCENTAGE' }
          ];

          for (const item of keysToMigrate) {
            if (dbConfigs[item.key] === undefined) {
              const localCopy = localStorage.getItem(item.key);
              if (localCopy) {
                let parsed = localCopy;
                try { parsed = JSON.parse(localCopy); } catch {}
                
                // Track this local migrated configuration as already baseline
                lastSyncedValuesRef.current[item.key] = JSON.stringify(parsed);
                
                await apiService.saveSystemConfigs({ key: item.key, value: parsed }).catch(()=>{});
              }
            }
          }
        } else {
          setDbHealthStatus('fallback');
        }
        isConfigsSyncReadyRef.current = true;
      } catch (err) {
        console.warn("System configurations fetch encountered network delay, utilizing local storage active settings:", err);
        setDbHealthStatus('fallback');
        setDbLastSyncTime(new Date().toLocaleTimeString('ar-SA'));
        isConfigsSyncReadyRef.current = true;
      }
    };
    initAndSyncConfigs();
  }, [isAuthenticated]);

  const updateConfigValueLocallyAndSilently = (key: string, value: any) => {
    // Avoid re-emitting POST for this key since it just arrived from Socket.io broadcast
    lastSyncedValuesRef.current[key] = JSON.stringify(value);
    
    // Save to local storage too so it is persistent across tab close/reload
    localStorage.setItem(key, typeof value === 'object' ? JSON.stringify(value) : String(value));
    
    switch (key) {
      case 'INVENTORY_SETTINGS': setInventorySettings(value); break;
      case 'SYSTEM_GENERAL_SETTINGS': setGeneralSettings(value); break;
      case 'SYSTEM_FINANCIAL_SETTINGS': setFinancialSettingsState(value); break;
      case 'ENABLE_FORCE_MAJEURE_PROTOCOL': setEnableForceMajeureProtocol(value !== false); break;
      case 'FORCE_MAJEURE_WINDOW_DAYS': setForceMajeureWindowDays(Number(value)); break;
      case 'SYSTEM_SECURITY_SETTINGS': setSecurityCustomSettings(value); break;
      case 'SYSTEM_NOTIFICATION_SETTINGS': setNotificationSettingsState(value); break;
      case 'SYSTEM_LOYALTY_SETTINGS': setLoyaltyCustomSettings(value); break;
      case 'ENABLE_PROVIDER_LEVELS': setEnableProviderLevels(value !== false); break;
      case 'ENABLE_LOYALTY_PROGRAM': setEnableLoyaltyProgram(value !== false); break;
      case 'DISABLE_CHAT_SYSTEM': setDisableChatSystem(false); break;
      case 'TICKET_RETENTION_DAYS': setTicketRetentionDays(value); break;
      case 'MARKETING_COMMISSION_PERCENTAGE': setMarketingCommissionPercentage(value); break;
      case 'ALLOW_ACCOUNT_DELETION': setAllowAccountDeletion(value === true); break;
      case 'ACTIVE_SETTLEMENT_METHOD': setActiveSettlementMethod(value); break;
      case 'SETTLEMENT_CONFIGURATION': setSettlementConfig(value); break;
      case 'PROMOTIONS': setPromotions(value); break;
      case 'ad_requests': setAdRequests(value); break;
      case 'internal_ads': setInternalAds(value); break;
      case 'lailah_season_requests': setSeasonRequests(value); break;
      case 'PLATFORM_MAIL_MESSAGES': setMailMessages(value); break;
      case 'SUPPORT_WORKING_HOURS': setWorkingHours(value); break;
      case 'SUPPORT_ALERT_MSG': setSupportAlertMsg(value); break;
      case 'ADMIN_ACTIVE_GATEWAY': setAdminActiveGateway(value); break;
      case 'ADMIN_ENABLED_GATEWAYS': setEnabledGateways(value); break;
      case 'sub_grid_columns': setSubColCount(Number(value)); break;
      case 'sub_grid_spacing': setSubSpacing(value); break;
      case 'sub_grid_align_center': setSubAlignCenter(value === true || value === 'true'); break;
      case 'PLATFORM_DATA': setPlatformData(value); break;
      case 'PARTIAL_PAYMENT_DEPOSIT_PERCENTAGE': setPartialPaymentDepositPercentage(Number(value)); break;
      default: break;
    }
    setDbLastSyncTime(new Date().toLocaleTimeString('ar-SA'));
  };

  const syncConfigItemToDB = (key: string, value: any) => {
    if (!isConfigsSyncReadyRef.current) return;
    const stringified = JSON.stringify(value);
    if (lastSyncedValuesRef.current[key] === stringified) {
      // Matching existing cached/loaded value, skip redundant POST
      return;
    }
    // Update ref immediately to prevent race triggers during rapid changes or state rendering batch
    lastSyncedValuesRef.current[key] = stringified;

    apiService.saveSystemConfigs({ key, value }).catch(e => {
      console.error(`Error saving config ${key}:`, e);
      // Clean up cache entry on hard failures so it retries on subsequent changes
      delete lastSyncedValuesRef.current[key];
    });
  };

