  // Booking Governance & Automated Lifecycle Logic
  useEffect(() => {
    if (userRole !== 'admin') return;

    const today = new Date();
    const todayStr = today.toISOString().split('T')[0];

    const updatedBookings = bookings.map(b => {
      let status = b.status;
      
      // 1. Handling Provider Confirmation Timeout (New -> Cancelled)
      if (b.status === 'جديد' && maxConfirmationPeriod !== 'مفتوح') {
        const match = maxConfirmationPeriod.match(/(\d+)/);
        const limitHours = match ? parseInt(match[0]) * (maxConfirmationPeriod.includes('أيام') || maxConfirmationPeriod.includes('يوم') ? 24 : 1) : 48;
        
        // Simulation: If created more than limit hours ago (mocking creation date with date - 1 day)
        const creationTime = new Date(b.createdAt || new Date(b.date).getTime() - 86400000).getTime();
        const diffHours = (today.getTime() - creationTime) / (1000 * 60 * 60);
        
        if (diffHours > limitHours) {
          status = 'ملغي';
        }
      }

      // 2. Handling Automated Execution (Confirmed -> Executed)
      if (b.status === 'مؤكد' && b.date <= todayStr) {
        status = 'منفذ';
      }

      // 3. Handling Payment Deadlines (Unpaid balance -> Cancelled)
      if (b.paymentStatus === 'جزئي' && b.status === 'مؤكد') {
        const providerObj = providers.find(p => p.name === b.providerName || p.name === b.hall);
        const deadlineStr = providerObj?.remainingBalanceDeadline || '3 أيام';
        const deadlineMatch = deadlineStr.match(/(\d+)/);
        const deadlineDays = deadlineMatch ? parseInt(deadlineMatch[0]) : 3;
        
        const bookingDate = new Date(b.date).getTime();
        const deadlineTime = bookingDate - (deadlineDays * 24 * 60 * 60 * 1000);
        
        if (today.getTime() > deadlineTime && todayStr < b.date) {
          // If past deadline and not fully paid
          status = 'ملغي';
        }
      }

      return { ...b, status };
    });

    const isDifferent = JSON.stringify(updatedBookings) !== JSON.stringify(bookings);
    if (isDifferent) {
      setBookings(updatedBookings);
    }
  }, [bookings, maxConfirmationPeriod, userRole, providers]);

  // Synchronize interactive tentative bookings with the bookingForm
  useEffect(() => {
    const handleTentativeChange = () => {
      const stored = localStorage.getItem('TENTATIVE_RESV');
      if (!stored) return;
      try {
        const parsed = JSON.parse(stored);
        setBookingForm(prev => {
          const notesText = `الوقت المختار عبر التقويم التفاعلي: من الساعة ${parsed.startTime} إلى ${parsed.endTime} (${parsed.hasConflict ? '⚠️ تعارض!' : 'جاهز وحر'})`;
          if (prev.startDate === parsed.date && prev.notes && prev.notes.includes(parsed.startTime)) {
            return prev;
          }
          return {
            ...prev,
            startDate: parsed.date,
            endDate: parsed.date,
            notes: notesText
          };
        });
      } catch (err) {
        console.warn("Error parsing tentative booking from event:", err);
      }
    };

    window.addEventListener('tentativeBookingChanged', handleTentativeChange);
    return () => {
      window.removeEventListener('tentativeBookingChanged', handleTentativeChange);
    };
  }, []);

