  useEffect(() => {
    let interval: any;
    if (selectedTicket && selectedTicket.status === 'مفتوحة') {
      interval = setInterval(() => {
        const createdDate = new Date(selectedTicket.createdAt).getTime();
        const elapsed = Math.floor((Date.now() - createdDate) / 60000); // minutes
        setActiveTicketTimer(elapsed);
      }, 60000); // Update every minute
      
      const createdDate = new Date(selectedTicket.createdAt).getTime();
      setActiveTicketTimer(Math.floor((Date.now() - createdDate) / 60000));
    } else {
      setActiveTicketTimer(null);
    }
    return () => clearInterval(interval);
  }, [selectedTicket]);

