  useEffect(() => {
    const migrateOldRecords = () => {
      let changed = false;

      // 1. Migrate Halls
      const storedHalls = localStorage.getItem('PLATFORM_HALLS_V4') || localStorage.getItem('PLATFORM_HALLS');
      if (storedHalls) {
        try {
          const parsed = JSON.parse(storedHalls);
          if (Array.isArray(parsed)) {
            const migrated = parsed.map((hall: any) => {
              if (!hall.providerId) {
                const provName = hall.providerName || hall.provider || '';
                const match = providersListForMigration.find((p: any) => p.name === provName);
                hall.providerId = match ? String(match.id) : '1';
                changed = true;
              }
              return hall;
            });
            if (changed) {
              localStorage.setItem('PLATFORM_HALLS_V4', JSON.stringify(migrated));
            }
          }
        } catch (e) {}
      }

      // 2. Migrate Bookings
      const storedBookings = localStorage.getItem('PLATFORM_BOOKINGS_V4') || localStorage.getItem('PLATFORM_BOOKINGS');
      if (storedBookings) {
        try {
          const parsed = JSON.parse(storedBookings);
          if (Array.isArray(parsed)) {
            let bookingsChanged = false;
            const migrated = parsed.map((booking: any) => {
              if (!booking.providerId) {
                const bProviderName = booking.providerName || booking.provider || '';
                const match = providersListForMigration.find((p: any) => p.name === bProviderName);
                booking.providerId = match ? String(match.id) : '1';
                bookingsChanged = true;
                changed = true;
              }
              return booking;
            });
            if (bookingsChanged) {
              localStorage.setItem('PLATFORM_BOOKINGS_V4', JSON.stringify(migrated));
            }
          }
        } catch (e) {}
      }

      // 3. Migrate Services
      const storedServices = localStorage.getItem('PLATFORM_SERVICES_V4') || localStorage.getItem('PLATFORM_SERVICES');
      if (storedServices) {
        try {
          const parsed = JSON.parse(storedServices);
          if (Array.isArray(parsed)) {
            let servicesChanged = false;
            const migrated = parsed.map((service: any) => {
              if (!service.providerId) {
                const sProviderName = service.providerName || service.provider || '';
                const match = providersListForMigration.find((p: any) => p.name === sProviderName);
                service.providerId = match ? String(match.id) : '1';
                servicesChanged = true;
                changed = true;
              }
              return service;
            });
            if (servicesChanged) {
              localStorage.setItem('PLATFORM_SERVICES_V4', JSON.stringify(migrated));
            }
          }
        } catch (e) {}
      }

      if (changed) {
        window.dispatchEvent(new Event('storage'));
      }
    };

    migrateOldRecords();
  }, [providersListForMigration]);

